import{_ as i,o as t,a,b as p}from"./app.DKoEZOcr.js";const _="/ascendc.github.io/pr/5487/assets/fixpipe_execution_flow_a2a3.BcXzEb56.png",s="/ascendc.github.io/pr/5487/assets/fixpipe_execution_flow_a5.DpRXh9eR.png",o="/ascendc.github.io/pr/5487/assets/fixpipe_buffer.Bg87n80d.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬出","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/cube_compute_store"},{"text":"总体说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/overall_description"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/overall_description.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/overall_description.md","lastUpdated":1786949923000}'),r={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_store/overall_description.md"};function c(n,e,u,d,l,I){return t(),a("div",null,[...e[0]||(e[0]=[p('<div><article class="markdown-body"><h1>总体说明<span id="ZH-CN_TOPIC_0000002538231192"></span></h1><p>矩阵计算的搬出是Ascend C编程框架中用于数据搬运的一类核心接口，主要实现L0C Buffer与Global Memory、L1 Buffer、Unified Buffer（UB）之间的数据高效传输。该接口系列提供了多种数据搬运模式，能够满足矩阵计算中的数据搬运需求，通常在Mmad接口后配合使用。</p><p>矩阵计算的搬出接口支持多种随路搬运场景，包括<strong>随路量化、随路ReLU、随路格式转换（NZ2ND、NZ2DN）、随路通道拆分（Channel Split）、随路通道合并（Channel Merge）、UB双目标模式</strong>。通过灵活配置不同的参数结构体，开发者可以精确控制数据的搬运路径、起始位置、搬运长度、随路搬运能力等关键信息，充分利用硬件的数据搬运能力，最大化算子的整体执行性能。</p><div data-filter="950,A3,910b"><p>矩阵计算的搬出整体流程如下图所示：</p></div><div data-filter="A3,910b"><p><strong>图1</strong> 矩阵计算的搬出整体流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>）</p><p><img src="'+_+'" alt></p></div><div data-filter="950"><p><strong>图2</strong> 矩阵计算的搬出整体流程图（<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>）</p><p><img src="'+s+'" alt></p></div><p>其中，Fixpipe Buffer不同的量化模式对应的内存排布如下：</p><p><strong>图3</strong> Fixpipe Buffer内存排布图</p><p><img src="'+o+'" alt></p></article></div>',1)])])}const g=i(r,[["render",c]]);export{b as __pageData,g as default};
